93	/// Iterator of a [`ResourcePaths`].
94	pub struct ResourcePathsIter<'a> {
95	  /// the patterns to iterate.
96	  pattern_iter: PatternIter<'a>,
97	  /// the glob iterator if the path from the current iteration is a glob pattern.
98	  glob_iter: Option<glob::Paths>,
99	  /// the walkdir iterator if the path from the current iteration is a directory.
100	  walk_iter: Option<walkdir::IntoIter>,
101	  /// whether the resource paths allows directories or not.
102	  allow_walk: bool,
103	  /// the pattern of the current iteration.
104	  current_pattern: Option<(String, PathBuf)>,
105	  /// whether the current pattern is valid or not.
106	  current_pattern_is_valid: bool,
107	  /// Current destination path. Only set when the iterator comes from a Map.
108	  current_dest: Option<PathBuf>,
109	}
