129	impl<'a> Iterator for ResourcePaths<'a> {
130	  type Item = crate::Result<PathBuf>;
131	
132	  fn next(&mut self) -> Option<crate::Result<PathBuf>> {
133	    self.iter.next().map(|r| r.map(|res| res.path))
134	  }
135	}
